import{_ as a,C as r,o as n,c as i,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Enterprise Agent Identity Planes Should Separate Rotating Assertions, Credential Leases and Propagation","description":"","frontmatter":{"title":"Enterprise Agent Identity Planes Should Separate Rotating Assertions, Credential Leases and Propagation","date":"2026-08-09","column":"industry-architecture","category":"daily","summary":"A file-backed workload identity should not become a long-lived execution credential. A stronger identity plane rereads the authoritative assertion at exchange time, derives a short-lived token, coalesces refreshes and controls log exposure, while treating propagation into child processes and tool boundaries as a separate governance problem.","item_id":"Q-20260809-02","source_research_object":"research/analysis/Q-20260809-02-rotating-assertion-short-lived-credential.md","source_reading_result":"research/reading/Q-20260809-02-workload-identity-exchange.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-09-rotating-assertion-short-lived-credential-cover-v2.jpg"},"headers":[],"relativePath":"en/industry/2026-08-09-rotating-assertion-short-lived-credential.md","filePath":"en/industry/2026-08-09-rotating-assertion-short-lived-credential.md","lastUpdated":1787407830000}'),d={name:"en/industry/2026-08-09-rotating-assertion-short-lived-credential.md"};function l(c,e,h,u,p,g){const t=r("ArticleCover");return n(),i("div",null,[o(t,{image:"/assets/covers/daily-2026-08-09-rotating-assertion-short-lived-credential-cover-v2.jpg",kicker:"Industry Architecture · Daily Research",title:"Enterprise Agent Identity Planes Should Separate Rotating Assertions, Credential Leases and Propagation",summary:"A file-backed workload identity should not become a long-lived execution credential. A stronger identity plane rereads the authoritative assertion at exchange time, derives a short-lived token, coalesces refreshes and controls log exposure, while treating propagation into child processes and tool boundaries as a separate governance problem.",version:"Q-20260809-02",status:"Daily Runtime V5 · 2026-08-09",languageHref:"/zh/industry/2026-08-09-rotating-assertion-short-lived-credential",languageLabel:"中文"}),e[0]||(e[0]=s(' # Enterprise Agent Identity Planes Should Separate Rotating Assertions, Credential Leases and Propagation <p>One of the most dangerous simplifications in enterprise agent architecture is treating the source of identity and the credential used during execution as the same object. A file-backed JWT assertion can represent workload identity, but it should not be copied into every task, tool process or remote execution environment as a durable bearer credential.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>A governed agent identity plane needs at least four distinct controls: authoritative identity source, exchange authority, short-lived execution credential and downstream propagation policy.</strong></p><p>Each answers a different question: who provides and rotates identity material; who may exchange it; how long the derived credential is valid; and which execution contexts are allowed to receive it. Short lifetime narrows an exposure window, but it does not prove least privilege or child-process isolation.</p><p>The sole analytical input is the <code>Q-20260809-02</code> Research Object. Production did not inspect additional call sites or perform new implementation research.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>This article is based on <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-02-rotating-assertion-short-lived-credential.md" target="_blank" rel="noreferrer">Research Object — Rotating Assertion to Short-Lived Runtime Credential</a>. Its evidence trail is <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-02-workload-identity-exchange.md" target="_blank" rel="noreferrer">Reading Result — Short-Lived Workload Identity Exchange</a>.</p><p>The selected implementation provides evidence for assertion rereading, short-lived exchange, caching, proactive refresh, concurrent refresh coalescing, transient-failure fallback and token redaction. It does not prove the broader Queue hypothesis that credentials are stripped from every child-process boundary.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The implementation reopens the assertion file for every exchange instead of reading it only at process startup. This allows the identity owner to rotate the assertion without requiring the agent process to restart.</p><p>The derived object is a short-lived ChatGPT access token. The recorded implementation boundaries include:</p><ul><li>assertion size and input validation;</li><li>endpoint protocol and network-policy checks;</li><li>a 30-second exchange timeout;</li><li>a maximum accepted token lifetime of one hour;</li><li>in-process caching of the current valid token;</li><li>proactive refresh and refresh after rejection;</li><li>coalescing many concurrent consumers behind one refresh;</li><li>continued use of a still-valid cached token after a transient proactive-refresh failure;</li><li>redaction of access-token values from debug output.</li></ul><h2 id="control-plane-separation" tabindex="-1">Control-plane separation <a class="header-anchor" href="#control-plane-separation" aria-label="Permalink to &quot;Control-plane separation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control layer</th><th>Primary object</th><th>What it governs</th><th>What it cannot replace</th></tr></thead><tbody><tr><td>Identity source</td><td>File-backed JWT assertion</td><td>External authority and rotation</td><td>Direct authorization to business APIs</td></tr><tr><td>Exchange authority</td><td>Federation rule + token endpoint</td><td>Who may derive a runtime credential</td><td>Downstream least privilege</td></tr><tr><td>Credential lease</td><td>Short-lived access token</td><td>Exposure duration and refresh</td><td>Child-process containment</td></tr><tr><td>Propagation policy</td><td>Process, MCP, hook, Git and remote boundaries</td><td>Which consumers receive credentials</td><td>Must be implemented and tested independently</td></tr></tbody></table><p>The table is a Research Center architecture synthesis based on the Research Object.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>Rereading the assertion preserves rotation authority outside the running process. If the original assertion were cached indefinitely at startup, the external identity could rotate while the runtime continued requesting credentials from stale material. Pull-based exchange resolves “what identity is authoritative now?” at the moment a credential is actually needed.</p><p>Refresh coalescing addresses another control-plane failure mode. When many tasks notice an approaching expiry at once, independent exchanges create a request storm and inconsistent failure handling. Shared refresh state turns one exchange into the process-local renewal authority.</p><p>Continuing to use a still-valid token after a transient refresh failure is an explicit availability tradeoff. It does not assert that the old token is universally safe; it relies on the fact that the token remains inside its previously issued bounded lease. Maximum lifetime, server-side revocation and federation policy still matter.</p><p>The most important boundary is that short-lived does not mean contained. A ten-minute token indiscriminately injected into every child process, log stream, hook or remote shell remains highly exposed during those ten minutes. Propagation needs separate evidence.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>An enterprise agent runtime should record the assertion source and last-read time, federation audience/subject constraints, current token issue and expiry times, refresh state and fallback use, authorized propagation scope, explicit environment stripping for child processes and diagnostic redaction status.</p><p>For CodeFlowMu, credentials should be injected at the narrowest consumer boundary rather than stored as global environment state. Any claim that child execution is isolated should be supported by concrete tests for environment construction, hooks, MCP servers, Git and remote execution.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The available evidence does not expose the complete federation-side audience, subject and scope policy, nor every integration call site of the new exchange crate. In-process caching also means the process that owns the exchange object can still access the current bearer token.</p><p>The supported conclusion is therefore a strong rotating-assertion-to-short-lived-credential mechanism, not a fully closed enterprise credential boundary.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>Further work should test fencing after token revocation, cross-process refresh when many processes share one rotating assertion, which child processes legitimately require delegation, and whether every propagation event can produce an auditable delegation receipt.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual separates Assertion File, Exchange Authority, Access Token Lease and Propagation Boundary. The orange dashed region explicitly marks child-process propagation controls that are not established by the selected evidence.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-02-rotating-assertion-short-lived-credential.md" target="_blank" rel="noreferrer">Research Object — Rotating Assertion to Short-Lived Runtime Credential</a>: sole analytical input.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-02-workload-identity-exchange.md" target="_blank" rel="noreferrer">Reading Result — Short-Lived Workload Identity Exchange</a>: traceability for implementation facts, limitations and open questions.</li></ol>',33))])}const v=a(d,[["render",l]]);export{b as __pageData,v as default};
